#!/usr/bin/env python3
"""Compose visual-plan/preview/contact.png from per-game screenshots.
Missing shots (offline/sandbox run) become labelled data-sheet tiles so the
sheet never silently claims a render that was not captured."""
import os
from PIL import Image, ImageDraw
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
GAMES = [{'folder': "desert-oasis", 'title': "Desert Oasis", 'ground': "#E0C288", 'item': "dates", 'itemN': 6, 'subjects': [{'name': "Camel", 'shape': "quad", 'fact': "Camels store fat in their humps and can walk for days without a drink."}, {'name': "Meerkat", 'shape': "human", 'fact': "Meerkats stand up tall on their back legs to watch for danger."}, {'name': "Tortoise", 'shape': "blob", 'fact': "Desert tortoises nap in cool underground burrows on hot days."}, {'name': "Jackal", 'shape': "quad", 'fact': "Jackals have big ears that help them hear tiny sounds far away."}, {'name': "Scorpion", 'shape': "bug", 'fact': "Scorpions glow a spooky blue-green under ultraviolet light."}, {'name': "Date Palm", 'shape': "plant", 'fact': "Date palms grow sweet fruit and give cool shade at the oasis."}]}, {'folder': "pirate-cove", 'title': "Pirate Cove", 'ground': "#D8C890", 'item': "coins", 'itemN': 7, 'subjects': [{'name': "Captain", 'shape': "human", 'fact': "The captain wears a big hat and reads the treasure map."}, {'name': "Parrot", 'shape': "bird", 'fact': "Parrots can copy words they hear again and again."}, {'name': "Crab", 'shape': "bug", 'fact': "Crabs walk sideways and snap with their strong claws."}, {'name': "Seagull", 'shape': "bird", 'fact': "Seagulls cry loudly to call their friends to food."}, {'name': "Sea Turtle", 'shape': "blob", 'fact': "Sea turtles swim thousands of miles across the ocean."}, {'name': "Treasure Chest", 'shape': "prop", 'fact': "Pirates kept gold coins and jewels in heavy wooden chests."}]}, {'folder': "moon-base", 'title': "Moon Base", 'ground': "#9AA0A8", 'item': "flags", 'itemN': 5, 'subjects': [{'name': "Astronaut", 'shape': "human", 'fact': "Astronauts wear suits that carry air, water, and warmth."}, {'name': "Moon Rover", 'shape': "prop", 'fact': "The Moon rover drove astronauts across the gray dusty ground."}, {'name': "Alien", 'shape': "blob", 'fact': "Storybook aliens have big eyes to see in the dark of space."}, {'name': "Helper Robot", 'shape': "human", 'fact': "Robots help astronauts by carrying tools and taking photos."}, {'name': "Satellite", 'shape': "prop", 'fact': "Satellites beam phone calls, maps, and TV down to Earth."}, {'name': "Moon Rock", 'shape': "blob", 'fact': "Moon rocks are full of tiny holes made by space crashes."}]}, {'folder': "rainbow-lab", 'title': "Rainbow Lab", 'ground': "#C8D8E8", 'item': "bubbles", 'itemN': 6, 'subjects': [{'name': "Scientist", 'shape': "human", 'fact': "Scientists ask questions and test ideas with fun experiments."}, {'name': "Flask", 'shape': "prop", 'fact': "Flasks hold colorful liquids that fizz and bubble in tests."}, {'name': "Magnet", 'shape': "prop", 'fact': "Magnets pull iron and steel without even touching them."}, {'name': "Robot Arm", 'shape': "prop", 'fact': "Robot arms lift and pour things too tricky for hands."}, {'name': "Crystal", 'shape': "prop", 'fact': "Crystals grow in neat shapes when liquids cool slowly."}, {'name': "Test Tube", 'shape': "prop", 'fact': "Test tubes hold tiny sips of liquid for safe mixing."}]}, {'folder': "castle-quest", 'title': "Castle Quest", 'ground': "#5DA34A", 'item': "shields", 'itemN': 5, 'subjects': [{'name': "Knight", 'shape': "human", 'fact': "Knights wore shiny armor made of linked iron rings and plates."}, {'name': "Horse", 'shape': "quad", 'fact': "Knights rode strong horses called steeds into parades."}, {'name': "Dragon", 'shape': "quad", 'fact': "Story dragons guard treasure and breathe pretend fire."}, {'name': "Catapult", 'shape': "prop", 'fact': "Catapults flung stones high over castle walls long ago."}, {'name': "Banner", 'shape': "prop", 'fact': "Banners showed a knight's colors so friends knew him far away."}, {'name': "Torch", 'shape': "prop", 'fact': "Torches lit dark castle halls with warm flickering flames."}]}, {'folder': "frog-pond", 'title': "Frog Pond", 'ground': "#63B04A", 'item': "tadpoles", 'itemN': 6, 'subjects': [{'name': "Frog", 'shape': "blob", 'fact': "Frogs lay eggs in water that hatch into wiggly tadpoles."}, {'name': "Duck", 'shape': "bird", 'fact': "Ducks have oily feathers so water rolls right off."}, {'name': "Pond Turtle", 'shape': "blob", 'fact': "Turtles sunbathe on logs to warm their cold bodies."}, {'name': "Heron", 'shape': "bird", 'fact': "Herons stand super still, then strike fast to catch fish."}, {'name': "Fish", 'shape': "fish", 'fact': "Fish breathe underwater with fluffy parts called gills."}, {'name': "Lotus", 'shape': "plant", 'fact': "Lotus flowers open in the morning and close at night."}]}, {'folder': "lighthouse-bay", 'title': "Lighthouse Bay", 'ground': "#9AA8B0", 'item': "buoys", 'itemN': 5, 'subjects': [{'name': "Sailor", 'shape': "human", 'fact': "Sailors read maps of the sea called charts to find their way."}, {'name': "Sailboat", 'shape': "prop", 'fact': "Sailboats catch the wind in big cloth sails to glide along."}, {'name': "Seagull", 'shape': "bird", 'fact': "Seagulls ride warm air going up without flapping."}, {'name': "Crab", 'shape': "bug", 'fact': "Crabs hide under rocks when big waves come in."}, {'name': "Fish", 'shape': "fish", 'fact': "Bay fish swim in glittery groups called schools."}, {'name': "Buoy", 'shape': "prop", 'fact': "Buoys float and bob to mark safe paths for boats."}]}, {'folder': "ant-city", 'title': "Ant City", 'ground': "#B08A5A", 'item': "crumbs", 'itemN': 7, 'subjects': [{'name': "Queen Ant", 'shape': "bug", 'fact': "The queen ant lays all the eggs for the whole colony."}, {'name': "Worker Ant", 'shape': "bug", 'fact': "Worker ants can lift things much heavier than themselves."}, {'name': "Aphid", 'shape': "blob", 'fact': "Ants keep aphids like cows and sip their sweet juice."}, {'name': "Ladybug", 'shape': "bug", 'fact': "Ladybugs munch the aphids that bother garden plants."}, {'name': "Leaf", 'shape': "plant", 'fact': "Leaf-cutter ants carry leaf pieces bigger than their bodies."}, {'name': "Tunnel", 'shape': "prop", 'fact': "Ant tunnels link many rooms deep under the ground."}]}, {'folder': "balloon-sky", 'title': "Balloon Sky", 'ground': "#8FC86A", 'item': "minis", 'itemN': 6, 'subjects': [{'name': "Pilot", 'shape': "human", 'fact': "Balloon pilots heat the air inside to float gently upward."}, {'name': "Cloud", 'shape': "blob", 'fact': "Clouds are crowds of tiny water drops floating in the sky."}, {'name': "Swallow", 'shape': "bird", 'fact': "Swallows swoop and zip to catch flies in mid-air."}, {'name': "Kite", 'shape': "prop", 'fact': "Kites climb when wind pushes their tilted faces upward."}, {'name': "Airplane", 'shape': "prop", 'fact': "Airplane wings lift the plane as air rushes past them."}, {'name': "Sunny", 'shape': "face", 'fact': "The Sun is a star that warms our whole wide world."}]}, {'folder': "feelings-stage", 'title': "Feelings Stage", 'ground': "#9A7FD0", 'item': "hearts", 'itemN': 5, 'subjects': [{'name': "Happy", 'shape': "face", 'fact': "Happy feels light and smiley, like sunshine in your chest."}, {'name': "Sad", 'shape': "face", 'fact': "Sad feels heavy, and crying can help the hurt flow out."}, {'name': "Angry", 'shape': "face", 'fact': "Angry feels hot and tight. Slow breaths can cool it down."}, {'name': "Scared", 'shape': "face", 'fact': "Scared keeps you safe by telling you to be careful."}, {'name': "Surprised", 'shape': "face", 'fact': "Surprised pops up fast when something unexpected happens."}, {'name': "Calm", 'shape': "face", 'fact': "Calm feels soft and quiet, like resting on green grass."}]}]
SH = os.path.join(ROOT, 'visual-plan', 'preview')
W, H, LABEL = 640, 448, 30
COLS = 2
def sheet_tile(g):
    im = Image.new('RGB', (W, H), (24, 26, 44))
    d = ImageDraw.Draw(im)
    d.rectangle([0, 0, W, 90], fill=tuple(int(g['ground'][i:i+2], 16) for i in (1, 3, 5)))
    d.text((16, 14), g['title'], fill=(255, 255, 255))
    d.text((16, 36), g['folder'] + '  (%d subjects, count: %s x%d)' % (len(g['subjects']), g['item'], g['itemN']), fill=(230, 230, 230))
    y = 110
    for s in g['subjects']:
        d.text((16, y), '- %s [%s] %.60s' % (s['name'], s['shape'], s['fact']), fill=(200, 210, 220))
        y += 26
    d.text((16, H - 30), 'no browser render in this env (needs network + Chrome)', fill=(255, 180, 120))
    return im
contact = Image.new('RGB', (W * COLS, (H + LABEL) * ((len(GAMES) + 1) // COLS)), (20, 22, 40))
d = ImageDraw.Draw(contact)
for i, g in enumerate(GAMES):
    p = os.path.join(SH, 'shot-%s.png' % g['folder'])
    try:
        im = Image.open(p).convert('RGB').resize((W, H))
    except Exception:
        im = sheet_tile(g)
    x, y = (i % COLS) * W, (i // COLS) * (H + LABEL)
    contact.paste(im, (x, y))
    d.text((x + 8, y + H + 7), g['folder'], fill=(255, 255, 255))
contact.save(os.path.join(SH, 'contact.png'))
print('wrote visual-plan/preview/contact.png', contact.size)
